import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const STATUSES = ['신청', '마감', '마감 취소', '승인', '승인 취소', '반려'];
// 가정: 전표 취소는 신청·승인·마감 취소 상태에서만 허용한다 (전환표에 허용 상태가 없어 정한 값)
const CANCELABLE = ['신청', '승인', '마감 취소'];

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '').trim();
  if (!/^[0-9]{1,18}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function optionalText(value: unknown, label: string, max: number): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) ' + max + '자 이하의 글자여야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr00405Controller {
  @Post('/journal-entries')
  @HttpCode(200)
  async createJournalEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const expenseResolutionId = idOf(data['expenseResolutionId'], '결의서 ID');
    idOf(data['accountSubjectId'], '계정과목 ID');
    const summary = optionalText(data['summary'], '적요', 500);
    const evidenceDetail = optionalText(data['evidenceDetail'], '증빙내역', 1000);
    return transaction(async (db) => {
      const resolutions = await db.query(
        'SELECT status, resolution_amount AS "amount" FROM expense_resolution WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: expenseResolutionId },
      );
      if (resolutions.length === 0) {
        throw new ApiError(404, 'EXPENSE_RESOLUTION_NOT_FOUND', '결의서를 찾을 수 없습니다.');
      }
      if (resolutions[0]['status'] !== '승인') {
        throw new ApiError(409, 'EXPENSE_RESOLUTION_NOT_APPROVED', '승인된 결의서만 분개·전표를 생성할 수 있습니다.');
      }
      // 가정: 결의 금액 전체를 차변·대변 한 줄씩 분개하므로 두 합계는 결의 금액과 같다
      const rows = await db.query(
        'INSERT INTO journal_entry (expense_resolution_id, entry_date, status, total_debit_amount, total_credit_amount, summary, evidence_detail, created_at, updated_at) '
          + 'VALUES (CAST(:resolutionId AS bigint), CAST(now() AS date), \'신청\', CAST(:amount AS numeric), CAST(:amount AS numeric), :summary, :evidenceDetail, now(), now()) '
          + 'RETURNING journal_entry_id AS "journalEntryId", status AS "status", total_debit_amount AS "totalDebitAmount", total_credit_amount AS "totalCreditAmount"',
        {
          resolutionId: expenseResolutionId,
          amount: String(resolutions[0]['amount']),
          summary,
          evidenceDetail,
        },
      );
      return rows[0];
    });
  }

  @Get('/journal-entries')
  async listJournalEntries(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const size = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, 200);
    const hasResolution = query['expenseResolutionId'] !== undefined && query['expenseResolutionId'] !== '';
    const resolutionId = hasResolution ? idOf(query['expenseResolutionId'], '결의서 ID') : null;
    const hasStatus = query['status'] !== undefined && query['status'] !== '';
    const status = hasStatus ? String(query['status']) : null;
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '전표 상태 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = ' WHERE (CAST(:resolutionId AS bigint) IS NULL OR expense_resolution_id = CAST(:resolutionId AS bigint))'
        + ' AND (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))';
      const items = await db.query(
        'SELECT journal_entry_id AS "journalEntryId", expense_resolution_id AS "expenseResolutionId", entry_date AS "entryDate", status AS "status", '
          + 'total_debit_amount AS "totalDebitAmount", total_credit_amount AS "totalCreditAmount", summary AS "summary", evidence_detail AS "evidenceDetail" '
          + 'FROM journal_entry' + where + ' ORDER BY journal_entry_id DESC LIMIT :limit OFFSET :offset',
        { resolutionId, status, limit, offset: page * limit },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM journal_entry' + where,
        { resolutionId, status },
      );
      return { items, page, size: limit, total: Number(counts[0]['total']) };
    });
  }

  @Post('/journal-entries/:journalEntryId/cancel')
  @HttpCode(200)
  async cancelJournalEntry(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const journalEntryId = idOf(req.params['journalEntryId'], '전표 ID');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM journal_entry WHERE journal_entry_id = CAST(:id AS bigint) FOR UPDATE',
        { id: journalEntryId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'JOURNAL_ENTRY_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      const current = String(found[0]['status']);
      if (current === '마감') {
        throw new ApiError(409, 'PERIOD_CLOSED', '마감된 기간의 전표는 마감 취소 전에는 취소할 수 없습니다.');
      }
      if (!CANCELABLE.includes(current)) {
        throw new ApiError(409, 'INVALID_STATE', '현재 상태에서는 전표를 취소할 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE journal_entry SET status = \'승인 취소\', updated_at = now() WHERE journal_entry_id = CAST(:id AS bigint) RETURNING status AS "status"',
        { id: journalEntryId },
      );
      return rows[0];
    });
  }
}

