import { useState } from 'react';
import { call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Form, Field, TextInput, NumberInput, Select, LookupSelect, RefName, ErrorText } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감 취소', '마감 취소'],
  ['승인', '승인'],
  ['승인 취소', '승인 취소'],
  ['반려', '반려'],
];
const CANCELABLE = ['신청', '승인', '마감 취소'];
const SIZE = 20;

export default function FnSfr00405Page({ role, notify }: PageProps) {
  const [draftResolution, setDraftResolution] = useState<number | string>('');
  const [draftStatus, setDraftStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [expenseResolutionId, setExpenseResolutionId] = useState<number | string>('');
  const [accountSubjectId, setAccountSubjectId] = useState<number | string>('');
  const [summary, setSummary] = useState('');
  const [evidenceDetail, setEvidenceDetail] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/journal-entries', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo, role],
  );

  function search() {
    setPageNo(0);
    setApplied({ expenseResolutionId: draftResolution, status: draftStatus });
  }

  function reset() {
    setDraftResolution('');
    setDraftStatus('');
    setPageNo(0);
    setApplied({});
  }

  function openCreate() {
    setExpenseResolutionId('');
    setAccountSubjectId('');
    setSummary('');
    setEvidenceDetail('');
    setCreating(true);
  }

  async function create() {
    if (expenseResolutionId === '') {
      throw new Error('결의서를 선택해 주세요.');
    }
    if (accountSubjectId === '') {
      throw new Error('분개에 사용할 계정과목 ID를 입력해 주세요.');
    }
    await call('POST', '/journal-entries', role, {
      expenseResolutionId,
      accountSubjectId,
      summary,
      evidenceDetail,
    });
    notify('전표를 생성했습니다.');
    setCreating(false);
    reload();
  }

  async function cancel() {
    if (!selected) {
      return;
    }
    await call('POST', '/journal-entries/' + String(selected['journalEntryId']) + '/cancel', role, {});
    notify('전표를 취소했습니다.');
    setSelected(null);
    reload();
  }

  if (selected) {
    const canCancel = CANCELABLE.includes(String(selected['status']));
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>전표 정보</h2>
          <Pairs
            items={[
              ['전표 ID', String(selected['journalEntryId'])],
              ['결의서 ID', <RefName table="expense_resolution" role={role} value={selected['expenseResolutionId']} />],
              ['전표 일자', <DateText value={selected['entryDate']} />],
              ['전표 상태', <Badge value={selected['status']} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>분개 금액</h2>
          <Pairs
            items={[
              ['차변 합계', <Num value={selected['totalDebitAmount']} />],
              ['대변 합계', <Num value={selected['totalCreditAmount']} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>적요와 증빙</h2>
          <Pairs
            items={[
              ['적요', String(selected['summary'] ?? '')],
              ['증빙내역', String(selected['evidenceDetail'] ?? '')],
            ]}
          />
        </section>
        {canCancel ? (
          <section className="box">
            <h2>전표 취소</h2>
            <Form
              onSubmit={cancel}
              submit="전표 취소"
              danger
              note="취소하면 전표 상태가 승인 취소로 바뀌며, 이 화면에서는 되돌릴 수 없습니다."
            />
          </section>
        ) : null}
      </div>
    );
  }

  return (
    <div>
      <Filters onSearch={search} onReset={reset}>
        <Field label="결의서 ID">
          <LookupSelect table="expense_resolution" role={role} value={draftResolution} onChange={setDraftResolution} placeholder="전체" />
        </Field>
        <Field label="전표 상태">
          <Select value={draftStatus} onChange={setDraftStatus} options={STATUS_OPTIONS} placeholder="전체" />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={openCreate}>전표 생성</button>
      </Band>
      {error ? <ErrorText text={error} /> : null}
      <DataTable
        columns={[
          { key: 'journalEntryId', label: '전표 ID' },
          { key: 'expenseResolutionId', label: '결의서 ID', render: (row) => <RefName table="expense_resolution" role={role} value={row['expenseResolutionId']} /> },
          { key: 'entryDate', label: '전표 일자', render: (row) => <DateText value={row['entryDate']} /> },
          { key: 'status', label: '전표 상태', render: (row) => <Badge value={row['status']} /> },
          { key: 'totalDebitAmount', label: '차변 합계', render: (row) => <Num value={row['totalDebitAmount']} /> },
        ]}
        rows={data?.items ?? []}
        onRowClick={(row) => setSelected(row)}
        empty={loading ? '불러오는 중입니다.' : '아직 등록한 전표가 없습니다. 전표 생성 버튼으로 첫 전표를 만들어 보세요.'}
      />
      <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      {creating ? (
        <Drawer title="전표 생성" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="전표 생성" note="승인된 결의서만 분개와 전표를 생성할 수 있습니다.">
            <Field label="결의서 ID" required>
              <LookupSelect table="expense_resolution" role={role} value={expenseResolutionId} onChange={setExpenseResolutionId} />
            </Field>
            <Field label="분개에 사용할 계정과목 ID" required>
              <NumberInput value={accountSubjectId} onChange={setAccountSubjectId} />
            </Field>
            <Field label="적요" wide>
              <TextInput value={summary} onChange={setSummary} multiline />
            </Field>
            <Field label="증빙내역" wide>
              <TextInput value={evidenceDetail} onChange={setEvidenceDetail} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
